# Mission 23: Ten Times Faster
# Count each distinct token; print 'token: count' in first-seen order.
import sys

words = sys.stdin.read().split()
seen = []
for w in words:
    if w not in seen:
        seen.append(w)
for w in seen:
    print(f"{w}: 1")  # BUG: always 1, and the membership scan is O(n^2)
